<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard - Stagium</title>@fonts
<style>:root{--bg:#f4f7fb;--surface:#fff;--text:#122033;--muted:#637083;--border:#d8e2ee;--accent:#155ea8;--soft:#eef4fb;--green:#147a50;--red:#b42318;font-family:"Instrument Sans",system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}.page{width:min(100%,1180px);margin:auto;padding:36px 22px}.header{display:flex;align-items:center;justify-content:space-between;gap:18px;border-bottom:1px solid var(--border);padding-bottom:22px}.brand{margin:0;color:var(--accent);font-size:13px;font-weight:800}.header h1{margin:4px 0 0}.tabs{display:flex;flex-wrap:wrap;gap:5px;border:1px solid var(--border);border-radius:9px;background:#fff;padding:4px}.tab{border-radius:6px;color:var(--muted);padding:9px 13px;font-size:13px;font-weight:750;text-decoration:none}.tab.active{background:var(--accent);color:#fff}.logout{border:0;background:transparent;color:var(--red);padding:9px 12px;font:inherit;font-size:13px;font-weight:750;cursor:pointer}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-top:18px}.card{border:1px solid var(--border);border-radius:12px;background:var(--surface);padding:20px;box-shadow:0 8px 24px rgba(18,32,51,.06)}.label{color:var(--muted);font-size:13px}.value{margin-top:5px;font-size:30px;font-weight:800}.panel{margin-top:18px}.panel h2{margin:0 0 16px;font-size:19px}.filter{display:flex;align-items:end;gap:12px;margin-top:24px}.filter label{flex:1;font-size:13px;font-weight:750}.filter select{width:100%;margin-top:7px;border:1px solid var(--border);border-radius:8px;background:#fff;padding:10px;font:inherit}.filter button,.clear{border:0;border-radius:8px;background:var(--accent);color:#fff;padding:11px 15px;font:inherit;font-size:13px;font-weight:750;text-decoration:none}.clear{background:var(--soft);color:var(--accent)}.charts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.chart-note{margin:-10px 0 16px;color:var(--muted);font-size:12px}.daily-chart{display:flex;align-items:end;gap:9px;height:220px;padding-top:12px}.day{display:flex;flex:1;height:100%;min-width:0;flex-direction:column;align-items:center;justify-content:end;gap:6px}.bar-value{font-size:11px;font-weight:800}.bar{width:min(100%,42px);min-height:3px;border-radius:6px 6px 2px 2px;background:linear-gradient(#3b82f6,var(--accent))}.day-label{overflow:hidden;width:100%;color:var(--muted);font-size:10px;text-align:center;white-space:nowrap}.student-bars{display:grid;gap:12px;max-height:245px;overflow:auto}.student-row{display:grid;grid-template-columns:minmax(110px,1fr) 2fr 32px;align-items:center;gap:9px}.student-name{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}.track{height:10px;border-radius:999px;background:var(--soft);overflow:hidden}.fill{height:100%;min-width:2px;border-radius:999px;background:var(--green)}.entry-count{font-size:12px;font-weight:800}.table-wrap{overflow:auto}table{width:100%;min-width:700px;border-collapse:collapse;font-size:14px}th,td{border-bottom:1px solid var(--border);padding:12px 10px;text-align:left}th{color:var(--muted);font-size:12px}.badge{border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.in{background:#e8f7ef;color:var(--green)}.out{background:#fff0ef;color:var(--red)}.empty{text-align:center;color:var(--muted);padding:28px}@media(max-width:850px){.header{align-items:flex-start;flex-direction:column}.tabs{width:100%;overflow:auto;flex-wrap:nowrap}.stats{grid-template-columns:1fr 1fr}.charts{grid-template-columns:1fr}}@media(max-width:520px){.page{padding:22px 14px}.stats{grid-template-columns:1fr}.card{padding:17px}.filter{align-items:stretch;flex-direction:column}.filter button,.clear{width:100%;text-align:center}}</style></head><body><main class="page">
<header class="header"><div><p class="brand">STAGIUM</p><h1>Dashboard</h1></div><nav class="tabs"><a class="tab active" href="{{ route('dashboard') }}">Dashboard</a><a class="tab" href="{{ route('courses.index') }}">Cursos</a><a class="tab" href="{{ route('students.index') }}">Alunos</a><a class="tab" href="{{ route('companies.index') }}">Empresas</a><a class="tab" href="{{ route('profile.edit') }}">Meus dados</a><form action="{{ route('logout') }}" method="POST">@csrf<button class="logout" type="submit">Sair</button></form></nav></header>
<form class="card filter" method="GET" action="{{ route('dashboard') }}"><label for="company_id">Selecionar empresa<select id="company_id" name="company_id"><option value="">Todas as empresas</option>@foreach($companies as $company)<option value="{{ $company->id }}" @selected($selectedCompany?->id===$company->id)>{{ $company->corporate_name }}</option>@endforeach</select></label><button type="submit">Aplicar filtro</button>@if($selectedCompany)<a class="clear" href="{{ route('dashboard') }}">Limpar</a>@endif</form>
<section class="stats"><div class="card"><div class="label">Alunos cadastrados</div><div class="value">{{ $totalStudents }}</div></div><div class="card"><div class="label">Empresas cadastradas</div><div class="value">{{ $totalCompanies }}</div></div><div class="card"><div class="label">Alunos vinculados</div><div class="value">{{ $linkedStudents }}</div></div><div class="card"><div class="label">Registros de ponto hoje</div><div class="value">{{ $logsToday }}</div></div></section>
<section class="charts"><div class="card"><h2>Frequência diária</h2><p class="chart-note">Percentual de alunos com entrada registrada nos últimos 7 dias.</p><div class="daily-chart">@foreach($frequency as $day)<div class="day"><span class="bar-value">{{ $day['percentage'] }}%</span><div class="bar" style="height:{{ max(3,$day['percentage']) }}%" title="{{ $day['present'] }} aluno(s)"></div><span class="day-label">{{ $day['label'] }}</span></div>@endforeach</div></div><div class="card"><h2>Presença por aluno</h2><p class="chart-note">Entradas registradas nos últimos 30 dias{{ $selectedCompany ? ' na empresa selecionada' : '' }}.</p><div class="student-bars">@forelse($studentFrequency as $item)<div class="student-row"><span class="student-name" title="{{ $item['name'] }}">{{ $item['name'] }}</span><div class="track"><div class="fill" style="width:{{ ($item['entries']/$maximumEntries)*100 }}%"></div></div><span class="entry-count">{{ $item['entries'] }}</span></div>@empty<p class="empty">Nenhum aluno encontrado para esta empresa.</p>@endforelse</div></div></section>
<section class="card panel"><h2>Últimos registros dos alunos</h2><div class="table-wrap"><table><thead><tr><th>Data e hora</th><th>Aluno</th><th>Empresa</th><th>Tipo</th><th>Distância</th></tr></thead><tbody>@forelse($lastLogs as $log)<tr><td>{{ $log->logged_at?->format('d/m/Y H:i') }}</td><td>{{ $log->student?->name }}</td><td>{{ $log->company?->corporate_name }}</td><td><span class="badge {{ $log->type }}">{{ $log->type==='in'?'Entrada':'Saída' }}</span></td><td>{{ $log->distance_meters }} m</td></tr>@empty<tr><td class="empty" colspan="5">Nenhum registro de ponto encontrado.</td></tr>@endforelse</tbody></table></div></section>
